// stores/cart.ts
import { ref, computed } from 'vue'
import { defineStore } from 'pinia'

export interface CartItem {
  id: string
  name: string
  price: number
  quantity: number
}

export const useCartStore = defineStore('cart', () => {
  const items = ref<CartItem[]>([])

  function addItem(item: Omit<CartItem, 'quantity'>, quantity = 1) {
    const existing = items.value.find((i) => i.id === item.id)
    if (existing) {
      existing.quantity += quantity
    } else {
      items.value.push({ ...item, quantity })
    }
  }

  function removeItem(id: string, quantity?: number) {
    const existing = items.value.find((i) => i.id === id)
    if (!existing) return

    if (quantity === undefined || existing.quantity <= quantity) {
      items.value = items.value.filter((i) => i.id !== id)
    } else {
      existing.quantity -= quantity
    }
  }

  function clear() {
    items.value = []
  }

  const total = computed(() =>
    items.value.reduce((sum, item) => sum + item.price * item.quantity, 0)
  )

  const itemCount = computed(() =>
    items.value.reduce((count, item) => count + item.quantity, 0)
  )

  return {
    items,
    addItem,
    removeItem,
    clear,
    total,
    itemCount,
  }
})
```

Notes: `addItem` merges into an existing line by quantity; `removeItem` takes an optional `quantity` (removes that many, or the whole line if omitted/exceeded). `total` and `itemCount` are reactive getters derived via `computed`.

